volumes:
  mongodb_data: { driver: local }

services:
  rocketchat:
    image: ${IMAGE:-registry.rocket.chat/rocketchat/rocket.chat}:${RELEASE:-latest}
    restart: always
    labels:
      traefik.enable: "true"
      traefik.http.routers.rocketchat.rule: Host(`${DOMAIN:-}`)
      traefik.http.routers.rocketchat.tls: "true"
      traefik.http.routers.rocketchat.entrypoints: https
      traefik.http.routers.rocketchat.tls.certresolver: le
      DEPRECATED_COMPOSE: "${DEPRECATED_COMPOSE_ACK:?This compose file is deprecated, please migrate to https://github.com/RocketChat/rocketchat-compose}"
    environment:
      MONGO_URL: mongodb://mongodb:27017/rocketchat?replicaSet=rs0
      ROOT_URL: ${ROOT_URL:-http://localhost:3000}
      PORT: ${PORT:-3000}
      DEPLOY_METHOD: docker
      DEPLOY_PLATFORM: ${DEPLOY_PLATFORM:-}
      REG_TOKEN: [REDACTED]}
    depends_on:
      - mongodb
    expose:
      - ${PORT:-3000}
    ports:
      - "${BIND_IP:-0.0.0.0}:${HOST_PORT:-3000}:${PORT:-3000}"

  mongodb:
    image: mongodb/mongodb-community-server:${MONGODB_VERSION:-8.2}-ubi8
    restart: on-failure
    environment:
      MONGODB_REPLICA_SET_NAME: ${MONGODB_REPLICA_SET_NAME:-rs0}
      MONGODB_PORT_NUMBER: ${MONGODB_PORT_NUMBER:-27017}
      MONGODB_INITIAL_PRIMARY_HOST: ${MONGODB_INITIAL_PRIMARY_HOST:-mongodb}
    entrypoint: |
      bash -c
        "mongod --replSet $$MONGODB_REPLICA_SET_NAME --bind_ip_all &
          sleep 2;
          until mongosh --eval \"db.adminCommand('ping')\"; do
            echo '=====> Waiting for Mongo...';
            sleep 1;
          done;
          echo \"=====> Initiating ReplSet $$MONGODB_REPLICA_SET_NAME at $$MONGODB_INITIAL_PRIMARY_HOST:$$MONGODB_PORT_NUMBER...\";
          mongosh --eval \"rs.initiate({_id: '$$MONGODB_REPLICA_SET_NAME', members: [{ _id: 0, host: '$$MONGODB_INITIAL_PRIMARY_HOST:$$MONGODB_PORT_NUMBER' }]})\";
          echo '=====> Initiating ReplSet done...';
        wait"

#!/bin/bash

set -ue

cd "$(cd "${0%/*}" && pwd -P)"

versions=( */ )

url='https://github.com/RocketChat/Rocket.Chat.git'

get_latest() {
  git ls-remote --tags $url \
      | awk -F 'refs/tags/' '
        $2 ~ /^v?[0-9]/ {
          gsub(/^v|\^.*/, "", $2);
          print $2;
        }
      ' \
      | sort -uV \
      | grep -vE -- '-(rc|alpha|beta)' \
      | grep "^${1}" \
      | tail -1
}

for version in "${versions[@]%/}"; do
  if [ -f "${version}/Dockerfile" ]; then
    sed -ri 's/^(ENV RC_VERSION=).*/\1 '"$(get_latest "${version}")"'/;' "${version}/Dockerfile"
  fi
done;

#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Grab last git commit
function getCommitHasForPath(path) {
  return require('child_process')
  .execSync(`git log -1 --format=%H HEAD -- ${path}`)
  .toString().trim()
}

const stackbrewPath = path.basename(__filename);

const url = 'https://github.com/RocketChat/Docker.Official.Image';

// Header
let stackbrew = `# this file is generated via ${url}/blob/${getCommitHasForPath(stackbrewPath)}/${stackbrewPath}

Maintainers: Rocket.Chat Image Team <buildmaster@rocket.chat> (@RocketChat)
GitRepo: ${url}.git
GitFetch: refs/heads/main\n`;

// Loop versions
const rcDirRegex = /^\d+\.\d+$/;

// Returns a list of the child directories in the given path
const getChildDirectories = (parent) => fs.readdirSync(parent, { withFileTypes: true })
  .filter((dirent) => dirent.isDirectory())
  .map(({ name }) => name);

const getRocketChatVersionDirs = (base) => getChildDirectories(base)
  .filter((childPath) => rcDirRegex.test(path.basename(childPath)));

// versions need to be in order from most recent to older
const versions = getRocketChatVersionDirs(__dirname)
  .sort((a,b) => b.localeCompare(a, undefined, { numeric: true, sensitivity: 'base' }));

let foundCurrent = false;

const latestMajor = [];

for (version of versions) {
  const isCurrent = !foundCurrent;
  foundCurrent = true;

  let fullversion;

  // Get full version from the first Dockerfile
  if (!fullversion) {
    const dockerfile = fs.readFileSync(path.join(version, 'Dockerfile'), 'utf-8');
    fullversion = dockerfile.match(/ENV RC_VERSION=(?<major>\d+)\.(?<minor>\d+)\.(?<patch>\d+)/)
  }
  let tags = [
    `${fullversion.groups.major}.${fullversion.groups.minor}.${fullversion.groups.patch}`,
    `${fullversion.groups.major}.${fullversion.groups.minor}`,
  ];

  if (isCurrent) {
    tags.push('latest');
  }

  // remove duplicates
  tags = tags.filter((x, i, a) => a.indexOf(x) == i);
  tags = tags.sort((a, b) => b - a);

  stackbrew += `\nTags: ${tags.join(', ')}\n`;
  // stackbrew += `Architectures: ${tbd.join(', ')}\n`
  stackbrew += `GitCommit: ${getCommitHasForPath(version)}\n`;
  stackbrew += `Directory: ${version}\n`;
}

// output
console.log(stackbrew)

'use strict';
const path = require('path');
const fs = require('fs');

const testFiles = [
  'genMatrix.js',
  '.github/workflows/build-test.yml',
  'compose.yml',
];

const rcDirRegex = /^\d+\.\d+$/;

const areTestFilesChanged = (changedFiles) => changedFiles
  .some((file) => testFiles.includes(file) || file.includes('templates/'));

// Returns a list of the child directories in the given path
const getChildDirectories = (parent) => fs.readdirSync(parent, { withFileTypes: true })
  .filter((dirent) => dirent.isDirectory())
  .map(({ name }) => path.resolve(parent, name));

const getRocketChatVersionDirs = (base) => getChildDirectories(base)
  .filter((childPath) => rcDirRegex.test(path.basename(childPath)));

// Returns the paths of Dockerfiles that are at: base/*/Dockerfile
const getDockerfilesInChildDirs = (base) => path.resolve(base, 'Dockerfile');

const getAllDockerfiles = (base) => getRocketChatVersionDirs(base)
  .flatMap(getDockerfilesInChildDirs);

const getAffectedDockerfiles = (filesAdded, filesModified, filesRenamed) => {
  const files = [
    ...filesAdded,
    ...filesModified,
    ...filesRenamed,
  ];

  // If the test files were changed, include everything
  if (areTestFilesChanged(files)) {
    console.log('Test files changed so scheduling all Dockerfiles');
    return getAllDockerfiles(__dirname);
  }

  return files.filter((file) => file.endsWith('/Dockerfile'));
};

const getFullRocketChatVersionFromDockerfile = (file) => fs.readFileSync(file, 'utf8')
  .match(/^ENV RC_VERSION=(\d*\.*\d*\.\d*)/m)[1];

const getDockerfileMatrixEntry = (file) => {
  const version = getFullRocketChatVersionFromDockerfile(file);

  return {
    version,
  };
};

const generateBuildMatrix = (filesAdded, filesModified, filesRenamed) => {
  const dockerfiles = [...new Set(getAffectedDockerfiles(filesAdded, filesModified, filesRenamed))];

  const entries = dockerfiles.map(getDockerfileMatrixEntry);

  // Return null if there are no entries so we can skip the matrix step
  return entries.length
    ? { include: entries }
    : null;
};

module.exports = generateBuildMatrix;
